import {createLearner,exposeHint,lessonState,completeActivity,submitAnswer,progress,metrics,evidence,migrateV2,createPlan,cancelPlan,planProgress,planState,timeMinutes,timeLabel,planStatus,achievements,settleAwards,timeline,saveProfile,attemptsFor,suggestions,localDate} from './learning.mjs?v=3.4.0';
import {openStore,loadLearner,saveLearner,saveRecording,recordingsFor,removeRecording} from './learning-store.mjs?v=3.4.0';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const QA=(new URLSearchParams(location.search).get('qa')||'').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,24);
const now=()=>new Date().toISOString(),today=()=>localDate(),dateText=at=>at?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'short',day:'numeric'}).format(new Date(at)):'历史时间未记录';
let learner,realLearner,preview=false,storageError='',manifest={},audio=null,audioToken=0,recording=null,recordToken=0,urls=[];
const ui={route:'home',homeSelected:false,subject:'en',lessonId:lessons[0].id,unit:'all',phase:0,question:0,filterSubject:'en',filterStage:'all',classStage:'启蒙阶段',planDraft:null,helperOpen:false,helperHidden:false,helperMessages:[],filterUnit:'all',filterLesson:'all',status:'all',search:'',range:'all',assignment:null,answerOpen:'',hints:{},month:today().slice(0,7),day:today(),editPlan:null,profileDraft:null,dialog:null};
const current=()=>getLesson(ui.lessonId),state=()=>lessonState(learner,ui.lessonId),scope=()=>scopedLessons(ui.filterSubject,ui.filterUnit,ui.filterLesson,ui.filterStage);
const icon=(name,cls='')=>`<img class="icon ${cls}" src="assets/icons/${name}.svg" alt="" aria-hidden="true">`;
const btn=(action,label,cls='button',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const chip=(text,cls='')=>`<span class="chip ${cls}">${text}</span>`;
const cartoonIcon=(frame,alt,cls='')=>`<img class="cartoon-icon ${cls}" src="assets/icons-cartoon-v34/${['book','practice','report','calendar','settings','chat'][frame]}.webp" alt="${esc(alt)}">`;
const awardArt=(id,alt)=>{const frame=['first-lesson','brave-speaker','unit-one','unit-two','l1-certificate','planned-days'].indexOf(id);return `<span class="award-sprite" role="img" aria-label="${esc(alt)}" style="background-position:${frame%3*50}% ${frame>2?100:0}%"></span>`;};
const art=(src,alt,cls='')=>`<img class="${cls}" src="assets/${src}" alt="${esc(alt)}">`;
const scene=(sc,alt,cls='')=>sc.frame==null?art(sc.image,alt,'scene '+cls):`<div class="scene panel-scene ${cls}" role="img" aria-label="${esc(alt)}" style="background-image:url('assets/${sc.image}');background-position:${sc.frame%2?'100%':'0'} ${sc.frame>1?'100%':'0'}"></div>`;
const header=(eyebrow,title,sub='',actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const percent=(a,b)=>b?Math.round(a/b*100)+'%':'—';
const bar=(a,b)=>`<div class="progress-bar" aria-label="完成${a}项，共${b}项"><i style="width:${b?Math.min(100,a/b*100):0}%"></i></div>`;
const library=createLibraryUI({esc,btn,icon,header,toast,navigate,render,subject:()=>ui.subject,selectedSubject:()=>ui.route==='home'&&!ui.homeSelected?null:ui.subject,stage:()=>ui.classStage,isPreview:()=>preview,dateText,setSubject:s=>{ui.subject=s;}});
function toast(t){$('#toast').textContent=t;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4500);}
function persist(){settleAwards(learner);if(!preview)saveLearner(learner).catch(()=>{storageError='本机保存暂不可用，请导出备份。';toast(storageError);});}
function stopAudio(){audioToken++;if(audio){audio.pause();audio.onended=null;}audio=null;}
function navigate(route){recordToken++;stopRecording();stopAudio();ui.route=route;if(route==='home')ui.homeSelected=false;ui.dialog=null;if(route!=='settings')ui.profileDraft=null;if(route!=='planner'){ui.planDraft=null;ui.editPlan=null;}render();window.scrollTo({top:0,behavior:'instant'});}
function beginLesson(id,phase){const l=getLesson(id);if(!l)return;ui.lessonId=id;ui.classStage=l.stage;ui.subject=l.subject;learner.subject=l.subject;learner.lastLesson=id;const c=lessonState(learner,id);c.startedAt??=now();ui.phase=phase??c.phase;ui.question=c.question||0;ui.assignment=null;ui.answerOpen='';persist();navigate('lesson');}
function assignmentOpen(id){ui.lessonId=id;ui.assignment=id;ui.question=0;ui.answerOpen='';ui.subject=getLesson(id).subject;navigate('homework');}
function voice(text,lang,completion){stopAudio();const entry=manifest[lang+'|'+text];if(!entry){toast('这段Serena音频尚未就绪，请先看文字。');return;}const token=audioToken,owner=learner;audio=new Audio(entry.file);audio.onended=()=>{if(token!==audioToken)return;audio=null;if(completion&&learner===owner){completion();persist();render();}};audio.onerror=()=>{stopAudio();toast('音频未能播放，请检查文件后重试。');};audio.play().catch(()=>toast('请再次点击朗读，或检查设备音量。'));}
function voiceButton(text,lang,label='听示范',cls='voice-button'){const e=manifest[lang+'|'+text];return btn('voice',icon('volume-2')+label,cls,`data-text="${esc(text)}" data-lang="${lang}" ${e?'':'disabled'} title="${e?'Serena · '+(e.provider==='Noiz'?'Noiz样音克隆':'Qwen原音色'):'Serena音频正在准备'}"`);}
function sidebar(){const routes=[['home','课程中心','house'],['classroom','我的课堂','book-open'],['homework','课后练习','clipboard-list'],['reports','学习报告','chart-no-axes-combined'],['planner','学习计划','calendar-days'],['knowledge','我的知识库','book-open'],['guide','亲子指南','heart']];return `<aside class="sidebar"><button class="brand" data-action="nav" data-route="home">${art('dodo.png','渡渡鸟学习伙伴')}<span>知识岛<small>LEARN · PLAY · GROW</small></span></button><nav aria-label="主导航">${routes.map(([r,t,i])=>btn('nav',icon(i)+`<span>${t}</span>`,(ui.route===r||r==='classroom'&&ui.route==='lesson'?'active ':'')+'nav-item',`data-route="${r}" ${ui.route===r?'aria-current="page"':''}`)).join('')}</nav><div class="sidebar-note">${art('medal.png','成长徽章')}<strong>成长，是每一次发现。</strong><p>记录自己的节奏，收集真实的进步。</p>${btn('nav','看看我的成长 '+icon('arrow-right'),'text-button','data-route="profile"')}</div><button class="account" data-action="nav" data-route="profile"><img src="${esc(learner.profile.avatar||'assets/dodo.png')}" alt="学生头像"><span><strong>${esc(learner.profile.name)}</strong><small>${learner.profile.stage||'填写我的学习档案'}</small></span>${icon('chevron-right')}</button></aside>`;}
function shell(body){return `<div class="shell" data-subject="${ui.route==='home'&&!ui.homeSelected?'en':ui.subject}">${sidebar()}<div class="workspace"><header class="topbar"><span>知识探索 / ${({home:'课程中心',classroom:'我的课堂',lesson:'正在学习',homework:'课后练习',reports:'学习报告',planner:'学习计划',guide:'亲子指南',profile:'个人成长',settings:'资料设置',knowledge:'我的知识库',configure:'课程配置',resource:'资源课堂'})[ui.route]}</span><div class="top-actions">${library.subjectCards()}${btn('helper-open',`<span class="restored-chat" aria-hidden="true"></span>`,'icon-button','aria-label="学习助手"')}${btn('nav',icon('settings'),'icon-button','data-route="settings" aria-label="个人设置"')}</div></header>${preview?`<div class="notice">审阅模式 · 操作不写入真实档案，不能读取或录制孩子的声音。${btn('preview','退出审阅','text-button')}</div>`:''}${QA?'<div class="qa-label">独立测试档案 · '+esc(QA)+'</div>':''}${storageError?'<div class="notice">'+storageError+'</div>':''}<main>${body}</main><footer>知识岛 v3 · 本机学习档案 · 英语L1体验6课 / 语文故事1课 <span>Serena AI女声 · 录音留在本机</span></footer></div></div>${assistant()}${dialog()}`;}
function platformBanner(){return `<section class="platform-banner" aria-labelledby="platform-banner-title"><div class="platform-banner-copy"><div class="eyebrow">KNOWLEDGE ISLAND · 知识岛</div><h1 id="platform-banner-title">不同的起点，<br>一起探索更大的世界。</h1><p class="banner-translation" lang="en">Different beginnings. A world to discover together.</p><p>无论年龄、来自哪里，或从哪一步开始，<br>让好奇心带着你，按自己的节奏学习与成长。</p><p class="banner-translation" lang="en">Every age. Every background. Every ability.<br>Learn and grow at your own pace.</p><div class="actions">${btn('browse-subjects','选择学习学科 '+icon('arrow-right'),'primary')}${btn('nav','上传我的学习材料','outline','data-route="knowledge"')}</div></div><img class="platform-banner-art" src="assets/banner-community-v34.webp" width="2172" height="724" alt="儿童、青年、成人与长者一起读书交流，包含不同文化背景和能力特点的学习者" fetchpriority="high"></section>`;}
function homeOverview(){const m=metrics(learner),pending=learner.plans.filter(p=>!p.cancelledAt&&planStatus(learner,p)!=='已完成').length;return `<div class="home-layout overview-layout"><div><div class="section-heading"><div><span class="eyebrow">YOUR LEARNING SPACE</span><h2>从这里，开启今天的探索</h2></div></div><p class="overview-intro">先选一个感兴趣的学科，也可以带着自己的材料来学习。</p><div class="overview-courses">${['en','zh'].map(id=>{const ls=lessons.filter(l=>l.subject===id),cm=metrics(learner,ls);return `<article class="card overview-course" data-subject="${id}"><div class="overview-cover">${scene(ls[0].stories[0].scene,subjects[id].name+'体验课程封面')}</div><div class="overview-course-copy"><span class="subject-tag" data-subject="${id}">${subjects[id].name} · 启蒙阶段</span><h3>${id==='en'?'英语生活探索':'语文故事探索'}</h3><p>${new Set(ls.map(l=>l.unitId)).size}个单元 · ${ls.length}个课节</p>${bar(cm.completed,ls.length)}<small>${cm.completed}/${ls.length}课核心学习已完成</small>${btn('subject-class','进入课堂 '+icon('arrow-right'),'primary course-enter',`data-subject="${id}"`)}</div></article>`;}).join('')}</div><p class="fine overview-availability">当前体验：启蒙阶段英语6课、语文1课；其他学科内容持续建设。个人材料可在知识库保存与阅读。</p><div class="section-heading"><h2>让每一次学习，都有方向</h2></div><div class="feature-grid">${[[1,'课后练习','找到学过的课与练习','homework'],[2,'学习报告','看看表现与下一步','reports'],[3,'我的计划','安排自己的学习节奏','planner']].map(([img,title,desc,r])=>btn('nav',cartoonIcon(img,title)+`<strong>${title}</strong><span>${desc}</span>`,'feature-tile',`data-route="${r}"`)).join('')}</div></div><aside class="aside-stack"><section class="card"><div class="between"><h3>我的学习总览</h3>${chip('全部学科')}</div><div class="ring" style="--pct:${m.required?m.activities/m.required*100:0}%"><div><strong>${percent(m.activities,m.required)}</strong><span>核心活动完成</span></div></div><p class="center quiet">${m.activities}/${m.required}项活动 · ${m.completed}/${lessons.length}课</p>${btn('progress-info','进度怎样计算？','text-button')}<p class="fine">根据实际学习记录更新。完成率反映学习参与，能力掌握需要更多作答与复习证据。</p></section><section class="card overview-plan"><span class="eyebrow">MY LEARNING PLAN</span><h3>给好奇心，留一点时间</h3><p>${pending?pending+'项学习计划待完成':'从一个适合自己的小目标开始。'}</p>${btn('nav','安排学习计划 '+icon('arrow-right'),'outline','data-route="planner"')}</section></aside></div>`;}
function home(){const sub=subjects[ui.subject],ls=lessons.filter(l=>l.subject===ui.subject),m=metrics(learner,ls),last=ls.find(l=>l.id===learner.lastLesson)||ls.find(l=>progress(learner,l.id).percent<100)||ls[0];const days=new Set(ls.flatMap(l=>Object.values(learner.lessons[l.id]?.activities||{}).filter(x=>x.at&&x.source!=='legacy').map(x=>localDate(x.at)))).size;return `<div class="home-layout"><div><div class="section-heading"><div><span class="eyebrow">MY LEARNING COURSES</span><h2>我的学习课程</h2></div>${btn('nav','全部课堂 '+icon('arrow-right'),'text-button','data-route="classroom"')}</div><section class="course-card"><div class="course-cover">${scene(ls[0].stories[0].scene,sub.name+'课程封面')}${chip('已加入体验','floating-chip')}</div><div class="course-copy">${chip('启蒙阶段 · '+(ui.subject==='en'?'基础听说':'故事理解'))}<h2>${ui.subject==='en'?'英语生活探索':'语文故事探索'}</h2><p>${ui.subject==='en'?'2个单元 · 6个课节 · 连续的故事与生活任务':'1个单元 · 1个课节 · 听读、理解与讲述'}</p>${bar(m.completed,ls.length)}<div class="between"><small>${m.completed}/${ls.length}课核心学习已完成</small>${btn('nav','进入课堂 '+icon('arrow-right'),'primary course-enter','data-route="classroom"')}</div></div></section><div class="section-heading"><h2>让练习，成为小小日常</h2><span class="quiet">学过的内容 · 随时再练</span></div><div class="feature-grid">${[[1,'课后练习','找到学过的课与练习','homework'],[2,'学习报告','看看表现与下一步','reports'],[3,'我的计划','安排自己的学习节奏','planner']].map(([img,title,desc,r])=>btn('nav',cartoonIcon(img,title)+`<strong>${title}</strong><span>${desc}</span>`,'feature-tile',`data-route="${r}"`)).join('')}</div><div class="section-heading"><h2>接着上次的发现</h2></div><section class="card continue-card">${scene(last.stories[learner.lessons[last.id]?.page||0].scene,last.zhTitle)}<div><span class="eyebrow">${unitLabel(units.find(u=>u.id===last.unitId))} / 第${last.order}课</span><h3>${lessonLabel(last,last.subject)}</h3><p>${progress(learner,last.id).done}/${progress(learner,last.id).total}项核心活动 · 断点已保存</p></div>${btn('resume','继续学习 '+icon('arrow-right'),'primary',`data-lesson="${last.id}"`)}</section></div><aside class="aside-stack"><section class="card"><div class="between"><h3>我的${sub.name}进度</h3>${chip('启蒙阶段')}</div><div class="ring" style="--pct:${m.required?m.activities/m.required*100:0}%"><div><strong>${percent(m.activities,m.required)}</strong><span>核心活动完成</span></div></div><p class="center quiet">${m.activities}/${m.required}项活动 · ${m.completed}/${ls.length}课</p>${btn('progress-info','进度怎样计算？','text-button')}<p class="fine">完成率反映学习参与，知识掌握需要更多作答与复习证据。</p></section><section class="card goal-card">${cartoonIcon(3,'学习计划')}<h3>按自己的节奏长大</h3><p>${learner.weeklyGoal?'每周目标：'+learner.weeklyGoal+'个学习日':'为自己定一个小目标。'}</p><div class="mini-stats"><div><strong>${days}</strong><span>实际学习日</span></div><div><strong>${learner.plans.filter(p=>!p.cancelledAt&&planStatus(learner,p)!=='已完成').length}</strong><span>待完成计划</span></div></div>${btn('nav','安排学习计划 '+icon('arrow-right'),'outline','data-route="planner"')}</section></aside></div>`;}
function lessonTiles(ls){return `<div class="lesson-strip" aria-label="课节选择">${ls.map(l=>{const p=progress(learner,l.id),started=!!learner.lessons[l.id]?.startedAt||p.done>0;return btn('select-lesson',`<span class="lesson-cover">${scene(l.stories[0].scene,l.zhTitle)}</span><span class="lesson-card-copy"><span class="lesson-card-meta">LESSON ${String(l.order).padStart(2,'0')} <span class="lesson-card-status">${p.percent===100?'已完成':started?'学习中 · '+p.percent+'%':'未开始'}</span></span><strong>${String(l.order).padStart(2,'0')}.${l.zhTitle}</strong><span class="lesson-card-focus" lang="${l.subject}">${esc(l.focus)}</span><span class="lesson-card-link">${ui.lessonId===l.id?'当前课节':'查看这一课'} ${icon('arrow-right')}</span></span>`,'lesson-tile '+(ui.lessonId===l.id?'current':''),`data-lesson="${l.id}" aria-pressed="${ui.lessonId===l.id}"`);}).join('')}</div>`;}
function classroom(){const us=units.filter(u=>u.subject===ui.subject&&u.stage===ui.classStage);if(!us.length)return header('MY CLASSROOM','我的'+subjects[ui.subject].name+'课堂','选择学习阶段，查看已有课程。')+classStagePicker()+empty('这个阶段的课程还在准备中','当前体验提供启蒙阶段英语6课、语文1课。');if(!us.some(u=>u.id===ui.unit))ui.unit=us[0].id;const ls=lessons.filter(l=>l.unitId===ui.unit);if(!ls.some(l=>l.id===ui.lessonId))ui.lessonId=ls[0].id;const l=current(),p=progress(learner,l.id);return header('MY CLASSROOM','我的'+subjects[ui.subject].name+'课堂','先选单元和课节，再开始今天的探索。')+classStagePicker()+`<section class="card curriculum-card"><div class="curriculum-top"><div>${chip(l.stage)}<span class="quiet">6—8岁体验内容 · L1课程序列</span></div><div class="unit-tabs">${us.map(u=>btn('unit',unitLabel(u),'tab '+(u.id===ui.unit?'active':''),`data-unit="${u.id}"`)).join('')}</div></div>${lessonTiles(ls)}</section><section class="lesson-preview card"><div class="preview-teaching"><div class="eyebrow">${l.stage} / ${unitLabel(units.find(u=>u.id===l.unitId))} / LESSON ${String(l.order).padStart(2,'0')}</div><h2 lang="${l.subject}">${lessonLabel(l,l.subject)}</h2><p>${l.summary}</p><div class="key-language"><span>${l.subject==='en'?"TODAY’S ENGLISH · 今天的英语":"今天的理解与表达"}</span><strong lang="${l.subject}">${l.focus}</strong></div><ul class="goals">${l.goals.map(g=>`<li>${icon('check')}${g}</li>`).join('')}</ul></div><div class="preview-illustration">${scene(l.stories[0].scene,l.zhTitle)}<div class="preview-example"><span>${l.subject==='en'?'LISTEN & DISCOVER':'听读示范'}</span><p lang="${l.subject}">${l.stories[0].text}</p>${voiceButton(l.stories[0].text,l.subject,'听本课示范')}</div></div><div class="lesson-preview-bottom"><div class="preview-progress">${bar(p.done,p.total)}<p>${p.done}/${p.total}项核心活动 · 约${l.minutes}分钟 · 5个学习环节</p></div><div class="actions">${btn('resume',p.done?'继续这一课 '+icon('arrow-right'):'开始这一课 '+icon('play'),'primary',`data-lesson="${l.id}"`)}${btn('open-assignment','看看本课练习','outline',`data-lesson="${l.id}"`)}</div></div></section><div class="section-heading"><h2>这一课，怎样学习？</h2><span>环节与课节分别选择</span></div><div class="phase-overview">${phases.map((x,i)=>btn('enter-phase',`<span>第${i+1}环节</span><strong>${x}</strong>`,'phase-card',`data-phase="${i}"`)).join('')}</div>`;}
function lesson(){const l=current(),c=state(),us=lessons.filter(x=>x.unitId===l.unitId),p=progress(learner,l.id);c.phase=ui.phase;const sub=ui.phase===0?prep(l):ui.phase===1?story(l):ui.phase===2?interaction(l):ui.phase===3?application(l):lessonReport(l);return header(`${subjects[l.subject].name} / ${l.stage} / L1 / ${unitLabel(units.find(u=>u.id===l.unitId))} / 第${l.order}课`,l.title,`${lessonLabel(l)} · ${p.done}/${p.total}项核心活动`,btn('nav','返回课堂目录','outline','data-route="classroom"'))+`<details class="lesson-picker"><summary>切换课节 · 当前第${l.order}课 ${lessonLabel(l)}</summary>${lessonTiles(us)}</details><nav class="phase-nav" aria-label="课内学习环节">${phases.map((x,i)=>btn('phase',`<span>0${i+1}</span>${x}`,'phase-tab '+(i===ui.phase?'active':''),`data-phase="${i}" ${i===ui.phase?'aria-current="step"':''}`)).join('')}</nav>${sub}${audio?`<div class="audio-dock">${icon('volume-2')}正在朗读 ${btn('audio-pause','暂停 / 继续','text-button')}${btn('audio-stop','结束朗读','text-button')}</div>`:''}`;}
function guideCard(text,img='thinking.png'){return `<aside class="guide-card">${art(img,'渡渡鸟知识小能手')}<div><strong>渡渡鸟的小提示</strong><p>${text}</p></div></aside>`;}
function prep(l){return `<section class="card prep-layout"><div>${chip('第1环节 · 课前准备')}<h2>今天，会发现什么？</h2><p>${l.summary}</p><ul class="goals">${l.goals.map(g=>`<li>${icon('check')}${g}</li>`).join('')}</ul>${l.terms.length?'<h3>先听一听，熟悉一下</h3><div class="vocab-list">'+l.terms.map(t=>`<div class="vocab-item ${termPictures[t]?'with-picture':''}"><strong lang="en">${t}</strong>${termPictures[t]?`<figure class="term-figure"><span class="term-picture" role="img" aria-label="${termPictures[t].label}" style="background-position:${termPictures[t].frame%3*50}% ${Math.floor(termPictures[t].frame/3)*50}%"></span><figcaption>${termPictures[t].label}</figcaption></figure>`:''}${voiceButton(t,l.subject,'听一听')}</div>`).join('')+'</div>':''}<div class="notice soft">准备一个小玩具或生活物品，后面可以邀请家人一起参与。</div>${btn('prep-done','准备好了，进入故事 '+icon('arrow-right'),'primary')}</div>${art('reading.png','渡渡鸟预习引导','prep-mascot')}</section>`;}
function story(l){const c=state(),i=c.page,s=l.stories[i];return `<div class="learning-layout"><section>${scene(s.scene,s.caption,'story-scene')}<div class="between story-caption"><span>故事画面 ${i+1} / ${l.stories.length}</span><strong>${s.caption}</strong></div><div class="card narration"><div><div class="eyebrow">${l.subject==='en'?'LISTEN TO THE STORY':'听见故事里的变化'}</div><p class="story-text" lang="${l.subject}">${s.text}</p></div>${btn('story-audio',icon('volume-2'),'round-button',`aria-label="朗读故事第${i+1}页" ${manifest[l.subject+'|'+s.text]?'':'disabled'}`)}</div><div class="page-controls">${btn('page',icon('arrow-left'),'icon-button',`data-page="${i-1}" ${i===0?'disabled':''} aria-label="上一页"`)}<div>${l.stories.map((s,j)=>btn('page',String(j+1),'page-dot '+(j===i?'active':''),`data-page="${j}" aria-label="故事第${j+1}页"`)).join('')}</div>${btn('page',icon('arrow-right'),'icon-button',`data-page="${i+1}" ${i===l.stories.length-1?'disabled':''} aria-label="下一页"`)}</div></section><aside class="aside-stack"><section class="card"><div class="eyebrow">第2环节 · 故事学习</div><h2>${s.caption.replace(/^\d+\s*·\s*/,'')}</h2><p>观察画面，听听发生了什么。可以重听，也可以自己读一读。</p>${chip(c.activities['story-'+i]?'本页听读已记录':'等你完成这页听读',c.activities['story-'+i]?'success':'')}<div class="actions">${btn('read-page','我已读完本页','outline')}</div><p class="fine">完整听完或明确确认读完才计入进度；翻页不增加完成率。</p>${btn('phase','去互动探索 '+icon('arrow-right'),'primary','data-phase="2"')}</section>${recordWidget(l,'story-'+i,s.text,'跟着示范，说一句')}${guideCard('不用着急。先用眼睛找一找，再试着说说自己的发现。')}</aside></div>`;}
function questionBlock(l,q){const a=attemptsFor(learner,l.id,q.id),last=a.at(-1),open=!last||ui.answerOpen===q.id,c=lessonState(learner,l.id),order=c.drafts?.[q.id]||[];return `<section class="card question-card"><div class="question-top"><div>${chip(q.transfer?'新情境 · 试着运用':'动手理解')}<h2 lang="${l.subject}">${q.prompt}</h2></div>${voiceButton(q.prompt,l.subject,'听题目')}</div>${q.instruction?`<p>${q.instruction}</p>`:''}${scene(q.scene,'练习情境：'+q.prompt,'question-scene')}${q.type==='sequence'?`<p class="quiet">按先后顺序点击三张卡片，再提交。</p><div class="sequence-options">${q.options.map((t,i)=>btn('order',`${chip(order.includes(i)?String(order.indexOf(i)+1):'待选择')}<strong>${t}</strong>`,'sequence-option '+(order.includes(i)?'selected':''),`data-q="${q.id}" data-value="${i}" ${!open||order.includes(i)?'disabled':''}`)).join('')}</div><div class="actions">${btn('submit-order','提交顺序','primary',`data-q="${q.id}" ${!open||order.length!==q.options.length?'disabled':''}`)}${btn('reset-order','重新排列','text-button',`data-q="${q.id}" ${!open?'disabled':''}`)}</div>`:`<div class="choices">${q.options.map((text,i)=>`<div class="choice ${last&&last.value===i&&!open?(last.correct?'correct':'incorrect'):''}">${btn('answer',`<span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${text}</span>`,'choice-answer',`data-q="${q.id}" data-value="${i}" ${!open?'disabled':''}`)}${voiceButton(text,l.subject,'','icon-button choice-audio')}</div>`).join('')}</div>`}${last&&!open?`<div class="feedback ${last.correct?'good':'try'}"><strong>${last.correct?'你发现了！':'再看看线索，也是一种进步。'}</strong><p>${last.correct?(q.success||'这次回答与当前情境一致。'):'回到画面找找线索；需要时可以主动查看提示。'}</p><small>第${a.length}次作答 · ${a[0].correct&&!a[0].hint?'首次独立答对':'首次表现已保留'}${last.hint?' · 本次有提示':''}</small><div>${btn('retry-question','再试一次','text-button',`data-q="${q.id}"`)}</div></div>`:btn('hint','给我一点提示','text-button',`data-q="${q.id}"`)}${(ui.hints[q.id]||c.hintExposure?.[q.id])&&open?'<div class="notice soft">'+(q.hint||'再看看画面里的关系。')+'</div>':''}</section>`;}
function interaction(l){ui.question=Math.min(ui.question,l.questions.length-1);return `<div class="task-tabs">${l.questions.map((q,i)=>btn('question',`任务${i+1}`,'tab '+(ui.question===i?'active':''),`data-question="${i}"`)).join('')}</div>${questionBlock(l,l.questions[ui.question])}<div class="between bottom-actions">${guideCard('先说说依据，再做选择。错了可以再试，首次表现会如实保留。')}${btn('phase','进入课后应用 '+icon('arrow-right'),'primary','data-phase="3"')}</div>`;}
function application(l){return `${questionBlock(l,l.transfer)}<div class="section-heading"><h2>把学到的，用在生活里</h2><span>理解之后，也试着表达</span></div><div class="learning-layout"><section class="card"><h3>今天的表达任务</h3><p>${l.talk}</p><div class="model-sentence"><strong>${l.demo}</strong>${voiceButton(l.demo,l.subject)}</div>${recordWidget(l,'oral',l.demo,'轮到我来说')}<label class="checkline"><input type="checkbox" id="oral-confirm" ${state().activities.oral?'checked':''}>我已尝试完成这次表达任务</label>${btn('oral-done','记录表达实践','outline')}<details class="adult-observations"><summary>陪伴者观察（可选）</summary><p class="fine">仅记录本次观察，不作为系统自动测评结果。</p>${l.observations.map((text,i)=>`<label class="checkline"><input type="checkbox" data-observation="${i}" ${state().observations[i]?'checked':''}>${text}</label>`).join('')}<label>本课陪伴备注<textarea id="lesson-note" maxlength="500">${esc(state().note)}</textarea></label></details><p class="fine">本人确认只记录练习完成，不代表系统已经评估发音。</p></section><aside class="aside-stack"><section class="card"><h3>课后还有新的小练习</h3><p>本课的应用任务与补充作业，会一起保存在“课后练习”中。之后回来，也能找到自己的记录。</p>${btn('open-assignment','查看本课作业 '+icon('arrow-right'),'outline',`data-lesson="${l.id}"`)}</section>${guideCard('先等待孩子尝试。需要帮助时，再一起听示范或看画面。','reading.png')}${btn('phase','查看本课报告 '+icon('arrow-right'),'primary','data-phase="4"')}</aside></div>`;}
function lessonReport(l){const p=progress(learner,l.id),m=metrics(learner,[l]);return `<section class="card celebration"><div>${chip('第5环节 · 本课学习摘要')}<h2>${p.percent===100?'每一步，都留下了发现。':'学习还在继续。'}</h2><p>核心活动 ${p.done}/${p.total} · 客观题首次独立正确 ${m.firstCorrect}/${m.firstCount} · 作答 ${m.tries}次</p>${bar(p.done,p.total)}<div class="actions">${btn('report-lesson','查看完整课节报告','primary',`data-lesson="${l.id}"`)}${btn('open-assignment','去复习本课作业','outline',`data-lesson="${l.id}"`)}</div></div>${art('reward.png','渡渡鸟为每一步努力鼓励你')}</section>${evidenceCards(l.subject)}<p class="fine">摘要与全局学习报告使用同一份记录，打开报告不增加学习进度。</p>`;}
function selectOptions(rows,value){return rows.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('');}
function filters(withStatus=false){const us=units.filter(u=>(ui.filterSubject==='all'||u.subject===ui.filterSubject)&&(ui.filterStage==='all'||u.stage===ui.filterStage));return `<section class="filters card"><label>学科<select data-filter="subject">${selectOptions([['all','全部学科'],...Object.entries(subjectCatalog)],ui.filterSubject)}</select></label><label>级别<select data-filter="stage">${selectOptions([['all','全部阶段'],...schoolStages.map(s=>[s,s])],ui.filterStage)}</select></label><label>单元<select data-filter="unit">${selectOptions([['all','全部单元'],...us.map(u=>[u.id,(ui.filterSubject==='all'?subjectCatalog[u.subject]+' · ':'')+unitLabel(u)])],ui.filterUnit)}</select></label><label>课节<select data-filter="lesson">${selectOptions([['all','全部课节'],...scopedLessons(ui.filterSubject,ui.filterUnit,'all',ui.filterStage).map(l=>[l.id,lessonLabel(l)])],ui.filterLesson)}</select></label>${withStatus?`<label>状态<select data-filter="status">${selectOptions([['all','全部状态'],['todo','待完成'],['review','建议复习'],['done','已练习']],ui.status)}</select></label><label class="search-field">搜索<input id="homework-search" placeholder="课名、知识点或表达" value="${esc(ui.search)}">${btn('search',icon('search'),'icon-button','aria-label="查找课后练习"')}</label>`:`<label>时间<select data-filter="range">${selectOptions([['all','全部记录'],['week','近7天'],['month','近30天']],ui.range)}</select></label>`}</section>`;}
const assignmentQuestions=l=>[l.transfer,...l.homework];
function assignmentMetrics(l){const ids=assignmentQuestions(l).map(q=>q.id),first=[],last=[];for(const id of ids){const a=attemptsFor(learner,l.id,id);if(a.length){first.push(a[0]);last.push(a.at(-1));}}return {total:ids.length,done:last.length,first:first.filter(a=>a.correct&&!a.hint).length,latest:last.filter(a=>a.correct).length,needs:last.some(a=>!a.correct||a.hint),at:last.map(a=>a.at).sort().at(-1)};}
function homework(){if(!ui.assignment&&!scope().length)return header('PRACTICE JOURNAL','课后练习','按学科、级别、单元与课节查找学习内容。')+filters(true)+empty('所选范围尚未配置课程','当前可体验英语、语文的启蒙阶段内容。没有内容时不会生成虚构作业。');if(ui.assignment){const l=getLesson(ui.assignment),qs=assignmentQuestions(l);ui.question=Math.min(ui.question,qs.length-1);return header('PRACTICE JOURNAL',l.zhTitle+' · 课后练习','本课应用与补充任务，同一记录随时继续。',btn('assignment-list','返回练习列表','outline'))+`<div class="task-tabs">${qs.map((q,i)=>btn('question',`练习${i+1}${attemptsFor(learner,l.id,q.id).length?' · 已尝试':''}`,'tab '+(ui.question===i?'active':''),`data-question="${i}"`)).join('')}</div>${questionBlock(l,qs[ui.question])}<div class="bottom-actions between">${btn('report-lesson','查看这节课的学习证据','text-button',`data-lesson="${l.id}"`)}${btn('assignment-next',ui.question<qs.length-1?'下一项练习 '+icon('arrow-right'):'回到练习目录','primary')}</div>`;}
 const query=ui.search.trim().toLowerCase(),ls=scope().filter(l=>learner.lessons[l.id]?.startedAt||progress(learner,l.id).done||attemptsFor(learner,l.id).length).filter(l=>{const m=assignmentMetrics(l);return (!query||(l.title+l.zhTitle+l.focus+allQuestions(l).map(q=>skills[q.skill]?.name).join('')).toLowerCase().includes(query))&&(ui.status==='all'||ui.status==='todo'&&m.done<m.total||ui.status==='review'&&m.needs||ui.status==='done'&&m.done===m.total);});return header('PRACTICE JOURNAL','课后练习','把学过的内容找回来，看看每一次练习的变化。')+filters(true)+`<div class="section-heading"><h2>我的练习档案</h2><span>${ls.length}个课节 · 首次与最近表现分别记录</span></div>${ls.length?'<div class="assignment-grid">'+ls.map(l=>{const m=assignmentMetrics(l);return `<section class="card assignment-card">${scene(l.transfer.scene,l.zhTitle)}<div>${chip(subjects[l.subject].name+' · '+unitLabel(units.find(u=>u.id===l.unitId)))}<h3>${lessonLabel(l)}</h3><p>${l.focus}</p>${bar(m.done,m.total)}<div class="comparison"><div><strong>${m.done}/${m.total}</strong><small>已尝试</small></div><div><strong>${percent(m.first,m.done)}</strong><small>首次独立正确 · ${m.first}/${m.done}</small></div><div><strong>${percent(m.latest,m.done)}</strong><small>最近正确 · ${m.latest}/${m.done}</small></div></div><p class="fine">${m.at?'最近练习 '+dateText(m.at):'等待第一次练习'}${m.needs?' · 建议再看看线索':''}</p>${btn('open-assignment',m.done?'继续 / 复习 '+icon('arrow-right'):'开始本课练习 '+icon('arrow-right'),'primary',`data-lesson="${l.id}"`)}</div></section>`;}).join('')+'</div>':empty('练习档案，从一节课开始','开始学习后，对应课节的练习会在这里归档。筛选没有结果时，也可以换一个范围。','去选择课堂','classroom')}`;}
function empty(title,text,label,route){return `<section class="card empty">${cartoonIcon(0,'学习档案')}<h2>${title}</h2><p>${text}</p>${label?btn('nav',label+' '+icon('arrow-right'),'primary',`data-route="${route}"`):''}</section>`;}
function statCards(m){return `<div class="stat-grid">${[[m.completed+'/'+scope().length,'核心学习完成课节'],[percent(m.firstCorrect,m.firstCount),'首次独立正确 · '+m.firstCorrect+'/'+m.firstCount],[percent(m.latestCorrect,m.answered),'最近正确 · '+m.latestCorrect+'/'+m.answered],[String(m.tries),'实际作答次数']].map(([v,t])=>`<section class="card stat-card"><strong>${v}</strong><span>${t}</span></section>`).join('')}</div>`;}
function evidenceCards(subject='all'){return `<div class="skill-evidence-grid">${Object.entries(skills).filter(([id,k])=>subject==='all'||k.subject===subject).map(([id,k])=>{const e=evidence(learner,id,ui.route==='reports'?scope():lessons,ui.route==='reports'?ui.range:'all');return `<section class="card evidence-card"><div class="between"><h3>${k.name}</h3>${chip(e.status,e.status==='较稳定'?'success':'')}</div><p>${e.samples?'首次独立正确 '+e.success+'/'+e.samples+' · '+e.dates+'个学习日期':'尚无新规则下的作答证据'}</p><small>${e.enough?'当前依据M1原型规则，仍需持续复习。':'至少5道不同题、2个学习日期，以及迁移或隔日复习证据后再判断。'}</small></section>`;}).join('')}</div>`;}
function reports(){if(!scope().length)return header('LEARNING INSIGHTS','学习报告','按学科、级别、单元与课节查看真实学习记录。')+filters()+empty('所选范围尚未配置课程','当前可体验英语、语文的启蒙阶段内容。请切换学科或级别。');const ls=scope(),m=metrics(learner,ls,ui.range);return header('LEARNING INSIGHTS','学习报告','从学科走到单元与课节，查看真实学习证据。',btn('export','导出学习档案 '+icon('download'),'outline'))+filters()+statCards(m)+`<div class="notice soft">完成率、作答正确比例和掌握证据分别展示。样本少时，百分比只是本次表现；口语未自动评分。</div><div class="report-layout"><section class="card"><div class="section-heading"><h2>课节学习概况</h2><span>点击可查看作答与学习记录</span></div><div class="report-table"><div class="table-head"><span>课节</span><span>核心活动</span><span>首次独立表现</span><span>最近表现</span><span></span></div>${ls.map(l=>{const x=metrics(learner,[l],ui.range),p=progress(learner,l.id);return `<div class="table-row"><div><strong>${lessonLabel(l)}</strong><small>${subjects[l.subject].name} · ${unitLabel(units.find(u=>u.id===l.unitId))}</small></div><span>${p.done}/${p.total} · ${p.percent}%</span><span>${x.firstCorrect}/${x.firstCount}</span><span>${x.latestCorrect}/${x.answered}</span>${btn('report-detail','查看','text-button',`data-lesson="${l.id}"`)}</div>`;}).join('')}</div></section><aside class="card"><h3>下一步，怎么安排？</h3><p>对需要帮助的知识点，先看具体任务，再把复习加入日历。系统不会自动改动你的计划。</p>${suggestions(learner,subjects[ui.subject]?ui.subject:'en').slice(0,2).map((s,i)=>`<div class="suggestion"><strong>${s.title}</strong><p>${s.reason}</p>${s.lessonId?btn('adopt-suggestion','加入复习计划','text-button',`data-index="${i}"`):''}</div>`).join('')}${btn('nav','打开学习计划','outline','data-route="planner"')}</aside></div>${ui.reportDetail?reportDetail(getLesson(ui.reportDetail)):''}<div class="section-heading"><h2>当前筛选范围的知识点证据</h2><span>M1 · 原型规则，不等同标准化测评</span></div>${evidenceCards(ui.filterSubject)}`;}
function reportDetail(l){const legacy=learner.lessons[l.id]?.legacySummary;return `<section class="card report-detail" id="report-detail"><div class="between"><div>${chip('L1 / '+unitLabel(units.find(u=>u.id===l.unitId)))}<h2>${lessonLabel(l)} · 具体证据</h2><p class="fine">以下展示本课全部历史作答，便于追溯首次表现；顶部指标按所选时间范围统计。</p></div>${btn('resume','回到本课','outline',`data-lesson="${l.id}"`)}</div>${allQuestions(l).map(q=>{const a=attemptsFor(learner,l.id,q.id),last=a.at(-1);return `<div class="evidence-row"><div><strong>${q.prompt}</strong><p>${skills[q.skill]?.name} · ${a.length?'首答：'+(a[0].correct&&!a[0].hint?'独立答对':a[0].hint?'有提示':'未答对')+' / 最近：'+(last.correct?'答对':'待练习')+' / '+a.length+'次作答':'尚未作答，不作能力判断'}</p>${a.length?`<details><summary>查看每次记录</summary>${a.map((x,i)=>`<p class="fine">第${i+1}次 · ${dateText(x.at)} · ${x.correct?'答对':'未答对'} · ${x.hint?'有提示':'未展示提示'}</p>`).join('')}</details>`:''}</div>${btn('review-specific','去复习','text-button',`data-lesson="${l.id}" data-q="${q.id}"`)}</div>`;}).join('')}${legacy?'<div class="notice soft">本课含v2历史汇总。原首答、次数、提示字段保留在旧规则记录中，不补造逐次时间，也不参与M1独立/跨日证据。</div><details><summary>查看旧版汇总</summary><pre>'+esc(JSON.stringify(legacy,null,2))+'</pre></details>':''}<h3>表达观察</h3><p>${learner.lessons[l.id]?.observations?.some(Boolean)?l.observations.filter((_,i)=>learner.lessons[l.id].observations[i]).join('；')+'（陪伴者记录）':'未记录观察，口语能力未评估。'}</p>${learner.lessons[l.id]?.note?'<blockquote>'+esc(learner.lessons[l.id].note)+'</blockquote>':''}</section>`;}
function makePlanDraft(p={}){const l=getLesson(p.lessonId)||current();return {subject:l.subject,stage:l.stage,unit:l.unitId,lessonId:l.id,date:ui.day,startTime:'',minutes:12,kind:'core',...p};}
function planForm(){const d=ui.planDraft??=makePlanDraft(),us=units.filter(u=>u.subject===d.subject&&u.stage===d.stage);if(!us.some(u=>u.id===d.unit))d.unit=us[0]?.id||'';const ls=lessons.filter(l=>l.unitId===d.unit&&l.subject===d.subject&&l.stage===d.stage);if(!ls.some(l=>l.id===d.lessonId))d.lessonId=ls[0]?.id||'';return `<section class="card plan-form"><div class="between"><h3>${ui.editPlan?'调整学习任务':'添加学习任务'}</h3>${cartoonIcon(3,'学习日历')}</div><form id="plan-form"><label>计划日期<input type="date" name="date" required value="${esc(d.date)}"></label><div class="form-columns"><label>学科<select name="subject" data-plan-filter="subject">${selectOptions(Object.entries(subjectCatalog),d.subject)}</select></label><label>级别<select name="stage" data-plan-filter="stage">${selectOptions(schoolStages.map(s=>[s,s]),d.stage)}</select></label></div><label>单元<select name="unit" data-plan-filter="unit" ${us.length?'':'disabled'}>${selectOptions(us.length?us.map(u=>[u.id,unitLabel(u)]):[['','暂无可选单元']],d.unit)}</select></label><label>课节<select name="lessonId" data-plan-filter="lessonId" ${ls.length?'':'disabled'}>${selectOptions(ls.length?ls.map(l=>[l.id,lessonLabel(l)]):[['','暂无可选课节']],d.lessonId)}</select></label>${d.lessonId?'<p class="selected-path">'+esc(lessonPath(getLesson(d.lessonId)))+'</p>':'<p class="notice soft">这个学科与阶段尚未配置课程，请先选择已有内容。</p>'}<label>任务类型<select name="kind">${selectOptions([['core','学习本课核心活动'],['homework','完成本课作业'],['review','复习一题']],d.kind)}</select></label><div class="form-columns"><label>开始时间<input type="time" name="startTime" value="${esc(d.startTime||'')}" ${ui.editPlan?'':'required'}></label><label>预计用时（分钟）<input type="number" min="3" max="90" name="minutes" value="${esc(d.minutes)}" required></label></div><p class="fine">所有学科共用这张日程表，重叠时段需先调整。旧任务未记录时间时保留“时间待定”。</p><div class="actions"><button class="primary" type="submit" ${ls.length?'':'disabled'}>${ui.editPlan?'保存调整':'加入计划'}</button>${ui.editPlan?btn('cancel-plan','取消','text-button'):''}</div></form></section>`;}
function gantt(plans){const timed=plans.filter(p=>p.startTime),start=Math.min(480,...timed.map(p=>timeMinutes(p.startTime))),end=Math.max(1260,...timed.map(p=>timeMinutes(p.startTime)+p.minutes)),span=end-start;return `<section class="card daily-gantt"><div class="section-heading"><h3>当天学习时间线</h3><span>全部学科 · 共享时段</span></div><div class="status-legend">${[['pending','待开始'],['active','进行中'],['done','已完成'],['overdue','逾期']].map(([id,t])=>`<span><i class="status-dot ${id}"></i>${t}</span>`).join('')}</div>${plans.length?`<div class="gantt-scroll"><div class="gantt-head"><span>课程与实际进度</span><div class="gantt-scale">${Array.from({length:6},(_,i)=>`<span>${timeLabel(Math.round((start+span*i/5)/15)*15)}</span>`).join('')}</div></div>${[...plans].sort((a,b)=>(a.startTime||'99').localeCompare(b.startTime||'99')).map(p=>{const status=planState(learner,p),pct=planProgress(learner,p),l=getLesson(p.lessonId);return `<div class="gantt-row"><div><strong>${esc(lessonPath(l))}</strong><small>${p.startTime?p.startTime+'—'+timeLabel(timeMinutes(p.startTime)+p.minutes):'时间待定'} · ${status.name} · ${pct}%</small></div><div class="gantt-track">${p.startTime?`<button class="gantt-task ${status.id}" data-action="edit-plan" data-plan="${p.id}" style="left:${(timeMinutes(p.startTime)-start)/span*100}%;width:${p.minutes/span*100}%" title="${esc(lessonPath(l))} ${p.startTime} ${pct}%" aria-label="调整${esc(lessonPath(l))}，${status.name}，完成${pct}%"><i data-progress="${pct}" style="width:${pct}%"></i></button>`:'<span class="unscheduled-label">补充开始时间后加入时间线</span>'}</div></div>`;}).join('')}</div>`:'<div class="empty compact"><p>今天还没有任务。添加后，不同学科会排列在同一条时间轴上。</p></div>'}</section>`;}
function planner(){const [year,month]=ui.month.split('-').map(Number),days=new Date(Date.UTC(year,month,0)).getUTCDate(),offset=(new Date(Date.UTC(year,month-1,1)).getUTCDay()+6)%7,selected=learner.plans.filter(p=>!p.cancelledAt&&p.date===ui.day);return header('MY LEARNING RHYTHM','学习计划','所有学科，共用一张日程表。先选择课程，再安排一个合适的时间。')+`<section class="card weekly-goal"><div><h3>我的每周目标</h3><p>设定适合自己的学习日，不必和别人比较。</p></div><label>每周<select id="weekly-goal">${selectOptions([1,2,3,4,5,6,7].map(x=>[String(x),String(x)]),String(learner.weeklyGoal||1))}</select>天</label>${btn('save-goal',learner.weeklyGoal?'更新目标':'设置目标','outline')}</section><div class="calendar-layout"><section class="card calendar"><div class="between"><h2>${year}年${month}月</h2><div class="actions">${btn('month-prev',icon('arrow-left'),'icon-button','aria-label="上个月"')}${btn('calendar-today','今天','text-button')}${btn('month-next',icon('arrow-right'),'icon-button','aria-label="下个月"')}</div></div><div class="weekdays">${['一','二','三','四','五','六','日'].map(x=>'<span>周'+x+'</span>').join('')}</div><div class="calendar-grid">${Array.from({length:offset},()=>'<div class="calendar-blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=ui.month+'-'+String(i+1).padStart(2,'0'),ps=learner.plans.filter(p=>!p.cancelledAt&&p.date===date);return btn('calendar-day',`<span>${i+1}</span><div class="day-tasks">${ps.slice(0,3).map(p=>{const st=planState(learner,p);return `<span class="day-task ${st.id}" data-subject="${getLesson(p.lessonId).subject}" title="${esc(lessonPath(getLesson(p.lessonId)))} · ${st.name}"><b>${subjectCatalog[getLesson(p.lessonId).subject]} · ${{pending:'待',active:'学',done:'完',overdue:'逾'}[st.id]}</b><i style="width:${planProgress(learner,p)}%"></i></span>`;}).join('')}${ps.length>3?'<small>+'+(ps.length-3)+'项</small>':''}</div>`,'calendar-day '+(date===ui.day?'selected ':'')+(date===today()?'today':''),`data-date="${date}" aria-label="${date}，${ps.length}项计划" aria-pressed="${date===ui.day}"`);}).join('')}</div><p class="fine">标签颜色区分学科；待、学、完、逾分别表示待开始、进行中、已完成与逾期，进度条来自实际记录。</p></section>${planForm()}</div><div class="section-heading"><h2>${ui.day} · 当天任务</h2><span>${selected.length}项</span></div>${gantt(selected)}<section class="card">${selected.length?selected.map(p=>{const st=planState(learner,p);return `<div class="plan-row"><span class="plan-status ${st.id}">${icon(st.id==='done'?'check':'calendar-days')}</span><div class="grow"><strong>${esc(lessonPath(getLesson(p.lessonId)))}</strong><p>${p.startTime?p.startTime:'时间待定'} · 预计${p.minutes}分钟 · ${st.name} · 实际进度${planProgress(learner,p)}%</p></div>${btn('start-plan','去完成','primary small',`data-plan="${p.id}"`)}${btn('edit-plan','改期 / 调整','text-button',`data-plan="${p.id}"`)}${btn('cancel-task','取消任务','text-button',`data-plan="${p.id}"`)}</div>`;}).join(''):'<div class="empty compact"><h3>今天的安排，由你决定</h3><p>选择一课，也为休息留一点时间。</p></div>'}</section>${learner.plans.some(p=>p.cancelledAt)?`<details class="card cancelled-plans"><summary>已取消的任务</summary>${learner.plans.filter(p=>p.cancelledAt).map(p=>`<div class="plan-row"><span>${esc(lessonPath(getLesson(p.lessonId)))} · ${p.date}</span>${btn('edit-plan','重新安排','outline',`data-plan="${p.id}"`)}</div>`).join('')}</details>`:''}<div class="section-heading"><h2>可以这样安排下一步</h2><span>解释依据 · 自主采纳</span></div><div class="suggestion-grid">${suggestions(learner,subjects[ui.subject]?ui.subject:'en').map((s,i)=>`<section class="card"><h3>${s.title}</h3><p>${s.reason}</p>${s.lessonId?btn('adopt-suggestion','选择时间安排 '+icon('arrow-right'),'outline',`data-index="${i}"`):btn('show-overdue','查看待完成安排','text-button')}</section>`).join('')}</div>${ui.showOverdue?'<section class="card"><h3>待调整任务</h3>'+learner.plans.filter(p=>!p.cancelledAt&&p.date<today()&&planStatus(learner,p)!=='已完成').map(p=>`<div class="plan-row"><span>${p.date} · ${esc(lessonPath(getLesson(p.lessonId)))}</span>${btn('edit-plan','调整日期','outline',`data-plan="${p.id}"`)}</div>`).join('')+'</section>':''}`;}
function profile(){const p=learner.profile,events=timeline(learner),earned=achievements(learner).filter(a=>a.earned);return `<section class="profile-banner"><img class="profile-photo" src="${esc(p.avatar||'assets/dodo.png')}" alt="${esc(p.name)}的头像"><div class="grow"><div class="eyebrow">MY LITTLE WORLD</div><h1>${esc(p.name)}</h1><p>${p.age==null?(p.legacyAgeLabel?'历史年龄段 '+esc(p.legacyAgeLabel):'年龄待填写'):p.age+'岁'} · ${p.stage||'学龄阶段待填写'}</p><small>从${dateText(learner.createdAt)}开始，在自己的节奏里成长</small></div><div class="profile-shortcuts"><a class="outline" href="#my-achievements">查看成就与奖状</a>${btn('settings',icon('settings')+' 设置','outline','aria-label="编辑个人资料与设置"')}</div></section><div class="section-heading"><h2>我的学科学习地图</h2><span>课程进度与能力证据分开看</span></div><div class="subject-comparison">${['en','zh'].map(sub=>{const ls=lessons.filter(l=>l.subject===sub),m=metrics(learner,ls);return `<section class="card subject-summary ${sub}"><div class="between"><h2>${subjects[sub].name}</h2>${chip('当前课程 L1')}</div><p>${m.completed}/${ls.length}课核心完成 · ${m.answered}道不同题已尝试</p>${bar(m.activities,m.required)}<p>学习投入：${m.days}个实际作答日；覆盖${new Set(learner.attempts.filter(a=>getLesson(a.lessonId)?.subject===sub).map(a=>a.skill)).size}类知识点。</p><div class="skill-tags">${Object.entries(skills).filter(([id,k])=>k.subject===sub).map(([id,k])=>chip(k.name+' · '+evidence(learner,id).status)).join('')}</div><div class="actions">${btn('subject-report','查看学科报告','text-button',`data-subject="${sub}"`)}${btn('subject-class','继续学习','outline',`data-subject="${sub}"`)}</div></section>`;}).join('')}</div><p class="fine">两科学习范围与证据量不同，这里不据此判定偏科。可以结合自己的目标，让学习投入更均衡。</p><div class="section-heading"><div><span class="eyebrow">MY ACHIEVEMENT GALLERY</span><h2 id="my-achievements">我的成就与奖状</h2></div><span>${earned.length}项成就已达成</span></div><div class="achievement-grid">${achievements(learner).map(a=>`<button class="achievement-card card ${a.earned?'earned':''}" data-action="achievement" data-achievement="${a.id}"><div class="achievement-art">${awardArt(a.id,a.name)}</div>${chip(a.earned?'已获得':'继续积累',a.earned?'gold':'')}<h3>${a.name}</h3><p>${a.description}</p>${bar(a.done,a.target)}<strong>${a.done}/${a.target}</strong><small>${a.earned?dateText(a.at):'达成后记录首次获得时间'}</small></button>`).join('')}</div>${Object.entries(learner.awards).some(([id])=>id.startsWith('legacy-'))?'<section class="card legacy-awards"><h3>带着旧时光，一起向前</h3><p>原样课成就已保留，不伪造新的获得时间。</p>'+Object.entries(learner.awards).filter(([id])=>id.startsWith('legacy-')).map(([id,a])=>chip(a.name+' · '+dateText(a.at))).join('')+'</section>':''}<div class="section-heading"><div><span class="eyebrow">MY GROWING STORY</span><h2>我的成长历程</h2></div>${btn('add-memory','记录一个重要时刻','outline')}</div><div class="timeline card">${events.length?events.map(e=>`<div class="timeline-row"><span class="timeline-mark ${e.type}">${icon(e.type==='award'?'award':e.type==='note'?'heart':'check')}</span><div><small>${dateText(e.at)}</small><h3>${esc(e.title)}</h3>${e.text?'<p>'+esc(e.text)+'</p>':''}${e.lessonId?btn('report-lesson','看看当时的学习证据','text-button',`data-lesson="${e.lessonId}"`):''}${e.type==='note'?'<span class="fine">个人补充记录</span>':''}</div></div>`).join(''):'<div class="empty compact"><h3>你的学习故事，从这里开始</h3><p>第一次探索、一次复习进步、一个重要时刻，都会慢慢留下。</p>'+btn('nav','去选择课堂','primary','data-route="classroom"')+'</div>'}</div><details class="card official-tools"><summary>官方内容管理 · 本机配置入口</summary><p>供官方课程编辑使用，当前为本机原型，尚无服务器权限隔离。</p>${btn('nav','打开课程后台','outline','data-route="configure"')}</details><section class="card privacy-card"><h3>属于你的本机学习档案</h3><p>资料、作答和录音留在当前浏览器，尚未连接云端账号或会员权益。可以导出备份，也可以导入原v2学习记录。</p><div class="actions">${btn('export','导出学习档案','outline')}${btn('import-legacy',learner.migration?'v2记录已导入':'导入v2学习记录','outline',learner.migration?'disabled':'')}${btn('preview',preview?'退出审阅':'进入不记进度的审阅模式','text-button')}</div></section>`;}
function settings(){ui.profileDraft??=structuredClone(learner.profile);const d=ui.profileDraft;return header('MY SETTINGS','个人设置','修改先保存在草稿中，点击保存后才会更新档案。',btn('cancel-settings','返回个人主页','outline'))+`<section class="card settings-card"><div class="avatar-editor"><img id="draft-avatar" src="${esc(d.avatar||'assets/dodo.png')}" alt="头像草稿预览"><div><h3>我的头像</h3><label class="outline upload-label">上传 / 替换头像<input type="file" id="avatar-file" accept="image/png,image/jpeg,image/webp" aria-label="选择学生头像"></label>${btn('reset-avatar','恢复默认','text-button')}<p class="fine">PNG / JPG / WebP · 最大1MB · 只保存在本机</p></div></div><form id="profile-form"><label>昵称<input name="name" value="${esc(d.name)}" required maxlength="20"></label><div class="form-columns"><label>年龄（自行填写）<input type="number" name="age" min="1" max="120" value="${d.age??''}" placeholder="可留空"></label><label>学龄阶段<select name="stage"><option value="">请选择</option>${schoolStages.map(x=>`<option ${d.stage===x?'selected':''}>${x}</option>`).join('')}</select></label></div><p class="fine">年龄、学龄与课程级别分别记录。更换学龄不会自动改变课程或赋予能力等级。</p><div class="actions"><button type="submit" class="primary">保存修改</button>${btn('cancel-settings','取消','outline')}</div></form></section>`;}
const guideSections=[['开始之前','先知道目标，再进入故事','和孩子一起看本课目标，准备一个生活物品。可以先指认、做动作，再慢慢开口。课堂顶部选课节，下面五个按钮是课内环节。'],['陪伴学习','多等待一点，让孩子先试试','先问“你发现了什么”“你是怎么知道的”，再提供线索。语文关注先后和依据，英语关注听懂情境与尝试交流。渡渡鸟是引导伙伴，不替孩子回答。'],['练习之后','复习可以换一个新场景','在“课后练习”按单元找到学过的课，保留首次表现，再看最近一次变化。不要用重复刷同一道题的正确率代表长期掌握。'],['怎样读报告','完成率与掌握证据分开看','完成率记录活动参与；首次独立表现反映第一次作答；知识点证据需要不同题、跨日期和迁移。数据不足是诚实提示，不是孩子能力差。'],['口语与录音','先听示范，再录音与回听','只有主动点击开始录音才会请求麦克风。录音存在当前浏览器，按课节分别保存，不上传、不自动评分。成人观察与系统判断有清晰区分。'],['计划与成长','找到适合自己的节奏','日历任务对应具体课节。建议说明依据，采纳后才加入计划。未完成可以改期，已获成就不会因中断被清空。'],['数据与适用范围','本机体验版本的使用说明','当前英语L1体验6课、语文故事1课，主要按6—8岁设计。个人学龄可扩展，但不代表已提供所有阶段课程。暂没有云端同步、付费会员或真实教师权限。']];
function guide(){return header('LEARN TOGETHER','亲子指南','陪伴孩子，也理解每一份学习记录。')+`<div class="guide-intro card">${art('reading.png','渡渡鸟与你一起读故事')}<div><h2>陪着发现，不急着给答案。</h2><p>听读、行动、表达和复习，都是学习的一部分。我们把过程记录下来，让下一步更有依据。</p></div></div><div class="guide-grid">${guideSections.map(([tag,title,text],i)=>`<section class="card"><span class="eyebrow">0${i+1} / ${tag}</span><h3>${title}</h3><p>${text}</p></section>`).join('')}</div>`;}
function dialog(){if(!ui.dialog)return '';const d=ui.dialog;return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(d.title)}"><div class="between"><h2>${d.title}</h2>${btn('close-dialog',icon('x'),'icon-button','aria-label="关闭"')}</div>${d.body}${d.actions||''}</section></div>`;}
function render(){library.beforeRender();const views={home:()=>platformBanner()+(ui.homeSelected?(subjects[ui.subject]?home():subjectHome()):homeOverview()),classroom:()=> (subjects[ui.subject]?classroom():header('MY CLASSROOM','我的'+subjectThemes[ui.subject].name+'课堂','选择阶段，查看自己配置的课程。')+classStagePicker())+library.courseCards(),lesson,homework,reports,planner,guide,profile,settings,knowledge:()=>library.page('knowledge'),configure:()=>library.page('configure'),resource:()=>library.page('resource')};$('#app').innerHTML=shell((views[ui.route]||home)());hydrateRecordings();library.hydrate();wakeData($('#app'),[preview?'preview':'real',ui.route,ui.subject,ui.filterSubject,ui.filterUnit,ui.filterLesson,ui.range].join('|'));if(ui.dialog)document.querySelector('.modal button')?.focus();}
function questionById(id){return allQuestions(current()).find(q=>q.id===id);}
