 if(a==='show-overdue'){ui.showOverdue=true;render();return;}
 if(a==='achievement'){const x=achievements(learner).find(x=>x.id===b.dataset.achievement);ui.dialog={title:x.name,body:`<p>${x.description}</p><p>当前进度 ${x.done}/${x.target} · ${x.earned?'首次获得：'+dateText(x.at):'条件达成后自动记录'}</p><p class="fine">成就鼓励真实参与和阶段进步，不作为能力或学历认证。</p>`};render();return;}
 if(a==='add-memory'){ui.dialog={title:'记录一个重要时刻',body:'<form id="memory-form"><label>这个时刻的名字<input name="title" maxlength="60" required placeholder="例如：第一次主动讲完一个故事"></label><label>我想记住<textarea name="text" maxlength="600" rows="4"></textarea></label><button class="primary" type="submit">保存成长记忆</button></form>'};render();return;}
