 if(a==='import-legacy'){if(preview){toast('审阅模式不读取真实旧档案。');return;}const key='language-island-v2'+(QA?'-qa-'+QA:''),raw=localStorage.getItem(key);if(!raw){toast(QA?'当前测试空间没有v2记录，不会读取正式档案。':'这个浏览器还没有v2学习记录。');return;}migrateV2(learner,JSON.parse(raw));await importLegacyRecordings();persist();render();toast('原记录已保留并导入；未知时间和逐次作答未补造。');return;}
