document.addEventListener('change',async e=>{const t=e.target;if(t.form?.id==='plan-form')ui.planDraft={...ui.planDraft,...Object.fromEntries(new FormData(t.form))};if(t.dataset.planFilter){ui.planDraft={...ui.planDraft,...Object.fromEntries(new FormData(document.querySelector('#plan-form')))};if(t.dataset.planFilter==='subject'||t.dataset.planFilter==='stage'){ui.planDraft.unit='';ui.planDraft.lessonId='';}if(t.dataset.planFilter==='unit')ui.planDraft.lessonId='';render();return;}if(t.dataset.classStage){ui.classStage=t.value;ui.unit='all';render();return;}if(t.dataset.observation!=null){state().observations[+t.dataset.observation]=t.checked;persist();}if(t.id==='lesson-note'){state().note=t.value;persist();}if(t.dataset.filter){if(t.dataset.filter==='stage'){ui.filterStage=t.value;ui.filterUnit='all';ui.filterLesson='all';}if(t.dataset.filter==='subject'){ui.filterSubject=t.value;if(subjects[t.value])ui.subject=t.value;ui.filterUnit='all';ui.filterLesson='all';}if(t.dataset.filter==='unit'){ui.filterUnit=t.value;ui.filterLesson='all';}if(t.dataset.filter==='lesson')ui.filterLesson=t.value;if(t.dataset.filter==='status')ui.status=t.value;if(t.dataset.filter==='range')ui.range=t.value;ui.reportDetail=null;render();}if(t.id==='avatar-file'){const file=t.files[0],draft=ui.profileDraft;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576){toast('请选择1MB以内的PNG、JPG或WebP图片。');return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=new Image();img.src=data;await img.decode();if(ui.route==='settings'&&ui.profileDraft===draft){draft.avatar=data;$('#draft-avatar').src=data;toast('头像草稿已更新，保存后才会应用。');}}catch{toast('这张图片无法读取，请换一张。');}}});
document.addEventListener('input',e=>{if(e.target.form?.id==='plan-form')ui.planDraft={...ui.planDraft,...Object.fromEntries(new FormData(e.target.form))};if(ui.route==='settings'&&e.target.form?.id==='profile-form')ui.profileDraft[e.target.name]=e.target.value;});
document.addEventListener('submit',e=>{e.preventDefault();try{const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='helper-form'){const question=String(values.question||'').trim().slice(0,200);if(question){ui.helperMessages.push({question,answer:helperAnswer(question)});render();}return;}if(f.id==='profile-form'){saveProfile(learner,{...ui.profileDraft,...values});persist();ui.profileDraft=null;navigate('profile');toast('个人资料已保存。');}if(f.id==='plan-form'){if(ui.editPlan){const old=learner.plans.find(p=>p.id===ui.editPlan);const test={...learner,plans:learner.plans.filter(p=>p.id!==old.id)};const valid=createPlan(test,values);old.rescheduledFrom??=[];old.rescheduledFrom.push({date:old.date,startTime:old.startTime||'',at:now()});Object.assign(old,{date:valid.date,kind:valid.kind,lessonId:valid.lessonId,minutes:valid.minutes,startTime:valid.startTime});delete old.cancelledAt;}else createPlan(learner,values);ui.day=values.date;ui.month=ui.day.slice(0,7);ui.editPlan=null;ui.planDraft=null;persist();render();toast('学习计划已保存。');}if(f.id==='memory-form'){learner.notes.push({id:crypto.randomUUID(),at:now(),title:values.title.trim(),text:values.text.trim()});persist();ui.dialog=null;render();}}catch(error){toast(error.message);}});
function recordWidget(l,tag,text,title){if(preview)return `<section class="card recording-widget"><h3>${title}</h3><p>${text}</p><p class="fine">审阅模式不读取或录制孩子的声音。</p></section>`;return `<section class="recording-widget" data-recording-key="${learner.id+'|'+l.id+'|'+tag}"><div class="eyebrow">SPEAK · LISTEN · TRY AGAIN</div><h3>${title}</h3><p lang="${l.subject}">${text}</p><div class="actions">${btn('record-start',icon('mic')+' 开始录音','outline small',`data-tag="${tag}" data-text="${esc(text)}" ${recording?'disabled':''}`)}${btn('record-stop',icon('square')+' 结束','text-button',recording?'':'disabled')}</div><div class="record-status fine">${recording?'正在录音 · 最长60秒':'主动开始才请求麦克风 · 本机保存 · 不自动评分'}</div><div class="recording-list"></div></section>`;}
async function hydrateRecordings(){urls.forEach(URL.revokeObjectURL);urls=[];if(preview)return;for(const el of document.querySelectorAll('[data-recording-key]')){try{const clips=await recordingsFor(el.dataset.recordingKey);if(!el.isConnected)continue;const host=el.querySelector('.recording-list');host.innerHTML='';if(!clips.length){host.innerHTML='<p class="fine">还没有录音。先听示范，再试着说一句。</p>';continue;}for(const r of clips.slice(0,3)){const url=URL.createObjectURL(r.blob);urls.push(url);const box=document.createElement('div');box.className='recording-clip';const audio=document.createElement('audio');audio.controls=true;audio.preload='metadata';audio.src=url;audio.setAttribute('aria-label','回听'+dateText(r.at)+'的录音');audio.addEventListener('play',()=>stopAudio());box.append(audio);const label=document.createElement('small');label.textContent=dateText(r.at);box.append(label);box.insertAdjacentHTML('beforeend',btn('record-delete','删除','text-button',`data-record="${r.id}"`));host.append(box);}}catch{if(el.isConnected)el.querySelector('.record-status').textContent='本机录音读取失败。';}}}
async function startRecording(tag,text){if(preview||recording)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('此浏览器不支持录音，可继续听示范与表达。');return;}stopAudio();const token=++recordToken,owner=learner,key=owner.id+'|'+ui.lessonId+'|'+tag;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==recordToken||preview||owner!==learner){stream.getTracks().forEach(t=>t.stop());return;}const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t)),recorder=new MediaRecorder(stream,type?{mimeType:type}:{}),chunks=[];const session={recorder,stream,key,timer:null};recording=session;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>{toast('录音中断，请检查麦克风。');stopRecording();};recorder.onstop=async()=>{clearTimeout(session.timer);stream.getTracks().forEach(t=>t.stop());if(recording===session)recording=null;const blob=new Blob(chunks,{type:recorder.mimeType});try{if(blob.size>100){await saveRecording({id:crypto.randomUUID(),key,blob,text,at:now(),learnerId:owner.id});toast('录音已保存在本机，可回听比较。');}}catch{toast('录音未能保存，请检查浏览器存储。');}if(!preview&&learner===owner)render();};recorder.start();session.timer=setTimeout(()=>stopRecording(),60000);render();}catch{stream?.getTracks().forEach(t=>t.stop());toast('未获得麦克风权限或设备不可用，可继续其他学习。');}}
function stopRecording(){if(recording&&recording.recorder.state!=='inactive')recording.recorder.stop();}
async function importLegacyRecordings(){const name='language-island-recordings'+(QA?'-qa-'+QA:'');if(indexedDB.databases){const list=await indexedDB.databases();if(!list.some(d=>d.name===name))return;}else return;const db=await new Promise((resolve,reject)=>{const r=indexedDB.open(name);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(!db.objectStoreNames.contains('clips')){db.close();return;}const clips=await new Promise((resolve,reject)=>{const req=db.transaction('clips').objectStore('clips').openCursor(),out=[];req.onsuccess=()=>{const c=req.result;if(c){out.push({key:c.key,...c.value});c.continue();}else resolve(out);};req.onerror=()=>reject(req.error);});db.close();for(const clip of clips){const [sub,tag]=clip.key.split('|'),l=lessons.find(l=>l.subject===sub);if(!l||!clip.blob)continue;const mapped=tag==='talk'?'oral':tag;await saveRecording({id:'legacy-'+learner.id+'-'+clip.key,key:learner.id+'|'+l.id+'|'+mapped,blob:clip.blob,at:clip.at||null,legacyTimeMissing:!clip.at,learnerId:learner.id});}}
async function init(){try{await openStore(QA||'main');await library.load();learner=await loadLearner()||createLearner();ui.subject=subjectThemes[learner.subject]?learner.subject:'en';ui.filterSubject=ui.subject;ui.lessonId=getLesson(learner.lastLesson)?learner.lastLesson:lessons[0].id;manifest=await fetch('audio/manifest.json',{cache:'no-store'}).then(r=>r.ok?r.json():{});render();}catch(error){learner??=createLearner();storageError='本机数据服务不可用：'+error.message;render();}}
init();
function classStagePicker(){return `<div class="class-stage-row"><label>学习阶段<select data-class-stage="true">${selectOptions(schoolStages.map(s=>[s,s]),ui.classStage)}</select></label><span class="quiet">阶段与课内环节分别选择 · L1为内部课程序列</span></div>`;}
function helperAnswer(q){if(/音频|声音|朗读/.test(q))return '点击题目旁的扬声器听示范。故事朗读完成后会记录这一页的听读；暂停、翻页和重复点击不会重复增加进度。';if(/进度|百分|完成率/.test(q))return '每课有8项核心活动：准备、3页听读、2项互动、1项迁移和表达实践。不同活动完成后才计入进度；完成率与知识掌握证据分开显示。';if(/计划|日历|时间|冲突/.test(q))return '所有学科共用学习计划。按学科、级别、单元和课节选好任务，再填写开始时间；时间重叠时请先调整。颜色和进度条会显示实际学习状态。';if(/录音|麦克风|发音/.test(q))return '先听示范，再主动点击开始录音。录音按课节保存在当前浏览器，可以回听或删除；目前不自动评估发音，也不上传录音。';if(/成就|奖|徽章/.test(q))return '点击成就卡可查看条件。未获得时置灰，达成后显示彩色并保留首次获得时间。完成活动会累计真实进度，不需要反复刷同一项。';if(/报告|分数|掌握/.test(q))return '报告分别展示首次独立表现、最近表现和知识点证据。题目、日期或迁移证据不足时，会显示“证据积累中”，不急着给能力定级。';if(/开始|课程|学习/.test(q))return '在“我的课堂”选择阶段、单元和课节，再进入课前准备。可以从听读、观察和动作开始，按照自己的节奏完成五个课内环节。';return '我目前提供课程与操作帮助，智能对话尚未开放。你可以询问课程、学习进度、报告、录音、计划或成就。关于当前故事，也可以先看学习目标，再回到画面寻找线索。';}
function assistant(){return `${ui.helperHidden?'':`<div class="learning-helper">${btn('helper-hide',icon('x'),'helper-hide','aria-label="收起悬浮助手"')}${btn('helper-open',art('thinking.png','渡渡鸟学习助手')+'<span>问问渡渡鸟</span>','helper-launch','aria-label="打开渡渡鸟学习助手"')}</div>`}${ui.helperOpen?`<aside class="helper-panel" role="dialog" aria-label="渡渡鸟学习助手"><header><div>${cartoonIcon(5,'学习助手')}<strong>渡渡鸟在这里</strong><small>课程与操作帮助 · 智能对话尚未开放</small></div>${btn('helper-close',icon('x'),'icon-button','aria-label="关闭助手面板"')}</header><div class="helper-conversation"><p class="helper-reply">学习遇到小问题，可以从这里问起。</p>${ui.helperMessages.slice(-6).map(m=>`<p class="helper-question">${esc(m.question)}</p><p class="helper-reply">${esc(m.answer)}</p>`).join('')}</div><div class="helper-quick">${['我该怎么开始？','学习进度怎么算？','如何安排计划？','录音在哪里？'].map(q=>btn('helper-quick',q,'text-button',`data-question="${q}"`)).join('')}</div><form id="helper-form"><label class="sr-only" for="helper-question">你的问题</label><input id="helper-question" name="question" maxlength="200" placeholder="问问课程与操作问题…" required><button class="primary small" type="submit">发送</button></form><p class="fine">问题仅用于当前页面的帮助展示，不会上传。</p></aside>`:''}`;}

function subjectHome(){return header('EXPLORE YOUR WORLD',subjectThemes[ui.subject].name+' · 从好奇开始','通过自己的材料和课程，按适合的节奏学习。')+`<section class="card"><h2>为自己搭建学习内容</h2><p>当前学科还没有内置课程。可以上传自己的学习材料，保存问题与笔记。</p><div class="actions">${btn('nav','上传学习材料','primary','data-route="knowledge"')}</div></section>`+library.courseCards();}
